import fs from 'node:fs'; import path from 'node:path'; import {inventory,digest} from './tests/r04/evidence.mjs'; import {checkDocuments,readDocuments,missingSharedBacklinks} from './tests/r03/link-check.mjs';
const p='.test-output/r04/correction-proposal-r1',docs=readDocuments(p+'/docs'),missing=[];
const address=(file,link)=>{const [rel,id]=link.split('#');return (rel?path.posix.normalize(path.posix.join(path.posix.dirname(file),rel)):file)+'#'+id;};
for(const [file,body] of Object.entries(docs).filter(([f])=>f.startsWith('design/')))for(const section of body.matchAll(/<a id="([^"]+)"><\/a>([\s\S]*?)(?=<a id="|$)/g)){
if(section[1]==='design-relations')continue;
for(const m of section[2].matchAll(/\[[^\]]+\]\(([^)]+)\)/g)){
if(/^[A-Za-z]+:/.test(m[1])||!m[1].includes('#'))continue;
const target=address(file,m[1]),tf=target.split('#')[0];if(tf===file)continue;
const refs=s=>[...s.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)].map(m=>address(tf,m[1]));
if(!(docs[tf]??'').split('\n').some(row=>{const c=row.split('|');return row.startsWith('|')&&refs(c[1]??'').includes(target)&&refs(c[2]??'').includes(file+'#'+section[1]);}))missing.push({from:file+'#'+section[1],target});
}}
const baseline=JSON.parse(fs.readFileSync('tests/evidence/r04/design-r1/integration-FCCoGx.json','utf8')), live=inventory('../kidea-workshop-pilot'),candidate=inventory(p),frozen=JSON.parse(fs.readFileSync('tests/evidence/r04/design-r1/correction-proposal-final.json','utf8'));
const changedCoreInputs=Object.entries(baseline.inputFiles).filter(([f,v])=>digest(fs.readFileSync(f))!==v.sha256).map(([f])=>f);
const candidateChanges=Object.entries(candidate).filter(([f,v])=>v.sha256!==frozen.allProposedHashes[f]).map(([f])=>f);
const appendOnly=Object.entries(frozen.targets).filter(([f])=>f!=='docs/design/architecture.md').every(([f,v])=>Buffer.from(v.base64,'base64').toString().replaceAll('\r\n','\n').trimEnd().startsWith(Buffer.from(baseline.pilot[f].base64,'base64').toString().replaceAll('\r\n','\n').trimEnd()+'\n\n'));
console.log(JSON.stringify({at:new Date().toISOString(),pilotUnchanged:JSON.stringify(live)===JSON.stringify(baseline.pilot),changedCoreInputs,candidateChanges,appendOnlyOutsideArchitecture:appendOnly,links:checkDocuments(docs),missingDesignBacklinks:missing,missingSharedBacklinks:missingSharedBacklinks(docs),architectureSha256:candidate['docs/design/architecture.md'].sha256,operationsSha256:candidate['docs/design/operations.md'].sha256}));
